window.POETRY_REGISTER("v5-strict-13-7-0-fb70253da2ba.js",{"poems":[[7771,2],[10379,2],[10743,2],[22581,2],[52352,2],[55309,2],[81870,7],[96439,7],[96477,7],[110938,7],[136038,7],[187980,7],[230808,7],[233355,7],[234163,7],[272337,7],[287932,7],[288947,7],[290723,7],[291947,7],[293298,7],[295844,7],[310208,7],[313059,7],[319517,7],[346413,9],[357880,9],[358940,9],[375286,10],[380849,10],[391501,13],[397535,13],[398237,13],[421131,8],[436413,8],[436948,8],[438244,8],[477827,8],[477851,8],[484181,8],[501772,8],[539100,8],[543891,8],[550197,8],[556443,8],[556444,8],[556717,8],[559207,8],[573751,8],[573987,8],[607092,8],[633761,15],[636948,15],[653688,5],[659978,5],[660703,5],[665051,5],[711576,5],[715318,5],[721885,5],[723307,5],[729145,5]],"pairs":[["亦幸有张伯英草圣兮龙腾蚪跃","摆长云兮捩回风",0],["君不能学哥舒横行青海夜带刀","西屠石堡取紫袍",1],["云是古之得道者西王母食之余","食之可以凌太虚",2],["欲动不动千变万化总是鳞皴皮","此奇怪物不可欺",3],["其碑题下署顺阳范的书并篆额","是范的为顺阳人",4],["此本系由王水照教授影印携归","此本有校录异文",5],["我闻丹山之凤非有八翼四足兮","又何羽毛之称奇",6],["吾嗟人愚不见天地造化之初难","乃云万物生自然",7],["常恨处非大荒穷北极寒之旷野","养违其性夭厥龄",8],["人于其间乃复雕镵刻画出智力","欲与造化追相倾",9],["吾闻石耳之生常在苍崖之绝壁","苔衣石腴风日炙",10],["愿得唐虞二八一十六相佐天子","雷风时至无错迷",11],["邑中之晳兮独能闯阃宎于轲邱","扈芷蘅兮荃其佩",12],["何曾见尔悬旌鸣佩朗装欲飞动","玉柱校立直以修",13],["谷高陵深兮矧昭阳穹庐之翻覆","万春千秋兮句曲",14],["我愿飞章夜扣丈人九仙之宝室","世路荆棘人心蓬",15],["机缄密运乎三百六十五度之外","浩浩万物资生成",16],["宁如文君当时深深深处深庭院","临邛亦免王孙怨",17],["不知谁何驷六虬兮上天作乐府","落笔殿前如有神",18],["虽然丈夫致君泽民事业匪仅此","要是此去无限隔",19],["岂料丰干院里撞著个匾头魔孽","尽把家私俱漏泄",20],["只如不收不放一句作么生判断","上元定是正月半",21],["君如夜寒不来旃昌黎之十操兮","将独歌之泪潺湲",22],["自怜今世少有赵昌徐熙水墨笔","谁写诸相争毫芒",23],["今弃我三十五岁父母玉成之身","一旦为氓受虏廛",24],["吾闻天目山中乃有千尺之悬泉","下赴大谷为奔川",25],["吾闻沙丘之马黄骊牝牡世莫知","九方皋去不复有",26],["吾闻匡山云锦九叠之胜神所栖","界天绝壁云为梯",27],["南藩大吏一月二十九日醉藩职","弗理莫敢辄玼瑕",28],["吾知子兮讵学商山采芝之黄绮","首阳食蕨之夷齐",29],["君如夜寒不来旃昌黎之十操兮","将独歌之泪潺湲",30],["自怜今世少有赵昌徐熙水墨笔","谁写诸相争毫芒",31],["今弃我三十五岁父母玉成之身","一旦为氓受虏廛",32],["君不见城中官长不忧耕不忧织","日日公堂命筵席",33],["有鹤有鹤飞鸣雪衣丹顶随风轻","两鹤飘然入紫清",34],["深莫深兮沈竿续蔓难测之小孤","西汇既潴彭蠡湖",35],["巙学士刘河间各专一技未是难","董生二者寔可取",36],["上有悲鸣噭噭离群啸匹之春鸿","下有萋萋断肠草",37],["胡生胡生何时与尔同上匡庐巅","足蹑星虹礼南斗",38],["谁言黄河之水东流到海不复回","海潮日日去复来",39],["谁言天上白云斯须改变如苍狗","日日白云飞海口",39],["复恐风雷一夕随龙变化不可测","短歌聊为歌清溪",40],["劝君不如且留读书饮酒过寒节","犹胜蹇驴出踏雪",41],["何时揽浮邱之袖兮拉安期之舄","瑶草春深挂萝席",42],["我闻此山乃为山灵咏真之洞天","蔽亏日月罗风烟",43],["不能使世之皆禹稷而无羿奡兮","虽德之生乃可耻",44],["不能使世之皆曾史而无盗跖兮","虽德之生已不伦",45],["时王太仓当轴但知坚请骸骨归","归后东征频丧师",46],["吁嗟汝乌何不呼雏辞南飞去北","从今勿攫道傍肉",47],["我思仙人乃在玉尘金鳌之两峰","以松为巢云作宫",48],["叶先生住在四万八千丈之天台","霞气直接东蓬莱",49],["我闻蓬莱之山乃在碧海之东隅","云霞五色成虚无",50],["又闻金华东观乃在西北之上京","台阶清切称天衢",50],["呜呼乎吾不知麟衰凤去将谁传","区区下界萦寒烟",51],["飞奴飞奴使尔腾空觅路冲苍茫","征云片片晴景光",52],["祇合深山大泽披发掉臂闲游行","万壑松声涤心耳",53],["男儿生世不得铭功勒石燕然山","岌峨空负头上冠",54],["爱君五色绚烂惊世骇俗之文章","秋鹰天马无比方",55],["吴君吴君但愿日日饮酒书八分","富贵于我如浮云",56],["吁嗟此琴尔何不伴诸葛居隆中","抱膝遂定三分功",57],["我亦不愿王家阿猷肩舆造我下","主客不具神潇洒",58],["我亦不愿娥皇女英哀哀攀我泣","重瞳驭遥叫不得",58],["姜侯乃煎麟角凤觜之胶重缀联","玉蜍吐水调松烟",59],["但得兄嫂一心善事阿母常喜悦","万里羁人慰愁绝",60],["一笑风前齐得丧世事塞翁之马","稽首谢狮王棒打",61]]});
